/**
 *
 * SidebarTrigger is a component that toggles the sidebar open or closed.
 *
 * [Live Demo](https://www.primereact.org/sidebar/)
 *
 * @module SidebarTrigger
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
/**
 * Defines passthrough(pt) options type in SidebarTrigger component.
 */
export type SidebarTriggerPassThroughType<E> = PassThroughType<SidebarTriggerInstance, E>;
/**
 * Defines passthrough(pt) options of SidebarTrigger component.
 */
export interface SidebarTriggerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SidebarTriggerPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SidebarTrigger component.
 */
export interface SidebarTriggerProps extends BaseComponentProps<SidebarTriggerInstance, unknown, SidebarTriggerPassThrough> {
    /**
     * The target sidebar to toggle.
     */
    target?: string | undefined;
}
/**
 * Defines valid state in SidebarTrigger component.
 */
export interface SidebarTriggerState {
}
/**
 * Defines the methods and properties exposed by SidebarTrigger component.
 */
export interface SidebarTriggerExposes {
}
/**
 * Instance of SidebarTrigger component.
 */
export type SidebarTriggerInstance = ComponentInstance<SidebarTriggerProps, SidebarTriggerState, SidebarTriggerExposes>;
